package net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DisplayNameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property display name of tenant config ")
  void test_display_name_v_o_builder() {
    Assertions.assertFalse(DisplayNameVO.nullValue().getDisplayName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DisplayNameVO.tryFrom(null).getDisplayName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", DisplayNameVO.from("one").getDisplayName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> DisplayNameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DisplayNameVO.from("one").toString());
  }
}
